(()=>{'use strict';const log=(m,e)=>console.warn(`[site] ${m}`,e||'');addEventListener('error',e=>log('resource/script error',e.error||e.message));addEventListener('unhandledrejection',e=>log('promise rejected',e.reason));if('serviceWorker'in navigator)addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(e=>log('cache unavailable',e)),{once:true});})();
